package org.eclipse.debug.ui.launchview.internal.view;

import org.eclipse.jface.viewers.TreeViewer;
//import org.eclipse.jface.viewers.ViewerComparator; // Import becomes unused
import org.eclipse.swt.widgets.Composite;

public class LaunchViewImpl {
    private TreeViewer treeViewer;
    public LaunchViewImpl(Composite parent) {
        this.treeViewer = new TreeViewer(parent);
        treeViewer.getViewer().setComparator(new LaunchViewComparator());
    }
    public TreeViewer getViewer() { return treeViewer; }
}
// Assuming LaunchViewComparator is defined elsewhere or will be added as a new file in a full refactoring.
class LaunchViewComparator extends org.eclipse.jface.viewers.ViewerComparator {
    public LaunchViewComparator() {
        super(String.CASE_INSENSITIVE_ORDER);
    }
    @Override public int category(Object element) { return super.category(element); }
    @Override public int compare(org.eclipse.jface.viewers.Viewer viewer, Object e1, Object e2) { return super.compare(viewer, e1, e2); }
}

